begin;
do $$
declare uid uuid; cid uuid; cid2 uuid; a uuid; b uuid; c uuid; other_staff uuid; original uuid; hu uuid=gen_random_uuid(); p jsonb; rowa jsonb; rowb jsonb; rowc jsonb; res jsonb; caught boolean;
begin
 select user_id into uid from public.payroll_members where role='admin' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 cid=(public.payroll_api('company_create','{"name":"Department salaries QA rollback"}')->>'id')::uuid;
 cid2=(public.payroll_api('company_create','{"name":"Other salaries QA rollback"}')->>'id')::uuid;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid,'DS-A','Dept A','ds-a@example.invalid','Teaching','2026-10-01') returning id into a;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid,'DS-B','Dept B','ds-b@example.invalid','Teaching','2026-10-01') returning id into b;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid,'DS-C','Dept C','ds-c@example.invalid','Teaching','2026-10-01') returning id into c;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid2,'DS-X','Other dept','ds-x@example.invalid','Teaching','2026-10-01') returning id into other_staff;
 insert into public.payroll_salaries(company_id,staff_id,effective_from,basic,da,hra,other) values(cid,c,'2026-10-01',20000,0,0,0) returning id into original;
 rowa=jsonb_build_object('staff_id',a,'expected_salary_id',null,'basic','20000','da','2000','hra','5000','cca','1000','other','1500','hod_allowance','2500');
 rowb=rowa||jsonb_build_object('staff_id',b);
 rowc=rowa||jsonb_build_object('staff_id',c,'expected_salary_id',original);
 p=jsonb_build_object('company_id',cid,'department','Teaching','effective_from','2026-11-01','reason','Reviewed department entry','request_id',gen_random_uuid(),'rows',jsonb_build_array(rowa,rowc));
 res=public.payroll_department_salaries(p);
 if res<>'{"initial":1,"recommended":1}'::jsonb then raise exception 'Mixed batch incorrect';end if;
 perform public.payroll_department_salaries(p);
 if (select count(*) from public.payroll_salaries where staff_id=a)<>1 or (select count(*) from public.payroll_increments where staff_id=c)<>1 then raise exception 'Replay duplicated salary';end if;
 if not exists(select 1 from public.payroll_salaries where id=original and basic=20000) or exists(select 1 from public.payroll_salaries where staff_id=c and effective_from='2026-11-01') then raise exception 'Revision bypassed approval';end if;
 if not exists(select 1 from public.payroll_increments where staff_id=c and status='recommended' and cca=1000 and hod_allowance=2500 and cum_gross=32000) then raise exception 'Components dropped';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb,rowc||'{"expected_salary_id":null}')));exception when others then caught=true;end;
 if not caught or exists(select 1 from public.payroll_salaries where staff_id=b) then raise exception 'Stale row or partial batch write';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb,rowc)));exception when others then caught=true;end;
 if not caught or exists(select 1 from public.payroll_salaries where staff_id=b) then raise exception 'Duplicate pending revision';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb||jsonb_build_object('staff_id',other_staff))));exception when others then caught=true;end;
 if not caught then raise exception 'Tenant crossing';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'department','Support','rows',jsonb_build_array(rowb)));exception when others then caught=true;end;
 if not caught then raise exception 'Department mismatch';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb,rowb)));exception when others then caught=true;end;
 if not caught then raise exception 'Duplicate staff selection';end if;
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb||'{"cca":"-1"}')));exception when others then caught=true;end;
 if not caught then raise exception 'Negative amount';end if;
 insert into public.payroll_runs(company_id,month,status,created_by,input_hash,snapshot) values(cid,'2026-12-01','locked',uid,'qa','{}');
 caught=false;begin perform public.payroll_department_salaries(p||jsonb_build_object('request_id',gen_random_uuid(),'rows',jsonb_build_array(rowb)));exception when others then caught=true;end;
 if not caught then raise exception 'Locked payroll bypass';end if;
 insert into auth.users(id,email,email_confirmed_at) values(hu,'ds-hr@example.invalid',now());
 insert into public.payroll_members values(cid,hu,'hr');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',hu,'role','authenticated')::text,true);
 caught=false;begin perform public.payroll_department_salaries(p);exception when others then caught=true;end;
 if not caught then raise exception 'HR salary escalation or replay disclosure';end if;
end$$;
rollback;
select 'PASS: mixed batch, no approval bypass, replay, atomic failure, stale versions, duplicate recommendations, tenant/department guards, amounts, locks and HR denial' as result;
